spec.expr:
sum by (instance, mssql_instance) (
  windows_mssql_memmgr_total_server_memory_bytes{instance="$instance", mssql_instance=~"$mssql_instance"}
)
/
sum by (instance, mssql_instance) (
  windows_mssql_memmgr_target_server_memory_bytes{instance="$instance", mssql_instance=~"$mssql_instance"}
)
